const root = ReactDom.createRoot(document.getElementById('root')); 

root.render(
    <React.StrictMode>      
        <Router>
        <div className='Index'>
        <Routes>
            <Route path = '/Home' component = {Home} />
            <div className='color_background'>
                <Route path = "/components/Header" element = {<Header />} />
            </div>
            <Route path = "/pages/Login" element = {<Login />} />

            <Home />
        </Routes>
        </div>
        </Router>

    </React.StrictMode>
);
